prompt --application/shared_components/user_interface/templates/region/skeleton_region
begin
wwv_flow_imp_shared.create_plug_template(
 p_id=>wwv_flow_imp.id(405505174037054869)
,p_layout=>'TABLE'
,p_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<section class="amc-TSkeletonRegion #REGION_CSS_CLASSES#" id="#REGION_STATIC_ID#" #REGION_ATTRIBUTES# aria-labelledby="#REGION_STATIC_ID#_heading" data-amc-delay="400" data-amc-min-show="350" data-amc-label-still="Still loading, %0 s" data-amc-label-slow="%0 is still loading" data-amc-label-done="%0 updated">',
'  <div class="amc-TSkeletonRegion-surface">',
'    <header class="amc-TSkeletonRegion-header">',
'      <span class="amc-TSkeletonRegion-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span>',
'      <h2 class="amc-TSkeletonRegion-title" id="#REGION_STATIC_ID#_heading">#TITLE#</h2>',
'      <span class="amc-TSkeletonRegion-elapsed" aria-hidden="true" hidden></span>',
'      <div class="amc-TSkeletonRegion-actions">#HELP##EDIT##CHANGE##COPY##DELETE##CREATE#</div>',
'    </header>',
'    <div class="amc-TSkeletonRegion-stage">',
'      <div class="amc-TSkeletonRegion-body">#BODY##SUB_REGIONS#</div>',
'      <div class="amc-TSkeletonRegion-skeleton" aria-hidden="true" hidden></div>',
'    </div>',
'    <footer class="amc-TSkeletonRegion-footer">#PREVIOUS##CLOSE##NEXT#</footer>',
'    <p class="amc-TSkeletonRegion-live" role="status" aria-live="polite"></p>',
'  </div>',
'</section>'))
,p_page_plug_template_name=>'AMC Skeleton Region'
,p_internal_name=>'AMC_TPL_SKELETON_REGION'
,p_javascript_file_urls=>'#APP_FILES#amc-templates/amc-tpl-skeleton-region.js'
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-skeleton-region.css'
,p_theme_id=>42
,p_default_label_alignment=>'RIGHT'
,p_default_field_alignment=>'LEFT'
,p_translate_this_template=>'N'
,p_template_comment=>'Motion region template for regions that refresh. Design principles: Doherty threshold: responses under about 400 ms feel immediate and must not show a loading state, because the flash itself disrupts; loading states: a skeleton that matches the real layout keeps spatial context and feels faster than a spinner, and shimmer respects reduced motion. How it works: on apexbeforerefresh of this region the script measures what is in the body right now, relative to the frame: every line of text, every form field and button, cards and other painted boxes, images, charts and canvases, and a rule under every report row. If apexafterrefresh arrives within data-amc-delay (400 ms) nothing is shown. Otherwise the skeleton is drawn over the body with one slow light sweep, the frame keeps its height so the page does not jump, the stage is aria-busy, and once shown it stays at least data-amc-min-show (350 ms) so it never flickers; then it fades out and a polite status says the region was updated. A 60 second failsafe removes it if no apexafterrefresh arrives. The body itself is never clipped, hidden or transformed. With the First load option an empty body at page load (lazy-loading regions) shows a synthetic shape until content arrives: set data-amc-skeleton="report|cards|form|text" and data-amc-skeleton-rows="5" as region Custom Attributes or on an element in the body. JavaScript API for your own Ajax: amcTplSkeletonRegion.start(element) and stop(element); shape(element) and state(element) for tests. English strings to translate, on the section element in the template or per region as Custom Attributes: data-amc-label-still Still loading, %0 s, data-amc-label-slow %0 is still loading, data-amc-label-done %0 updated (%0 = region title). Timing: data-amc-delay and data-amc-min-show in milliseconds. Reduced motion: a static skeleton with no sweep, pulse or fade. Forced colors: bones use GrayText.'
);
end;
/
